// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// SyncMenu Full menu sync — upsert categories and items in one request
	// (PUT /menu)
	SyncMenu(ctx context.Context, request SyncMenuRequestObject) (SyncMenuResponseObject, error)
	// UpdateAvailability Bulk stop-list and stock update
	// (POST /menu/availability)
	UpdateAvailability(ctx context.Context, request UpdateAvailabilityRequestObject) (UpdateAvailabilityResponseObject, error)
	// CreateMenuItem Add one item to an existing category
	// (POST /menu/items)
	CreateMenuItem(ctx context.Context, request CreateMenuItemRequestObject) (CreateMenuItemResponseObject, error)
	// UpdateMenuItem Change an item's structural fields
	// (PATCH /menu/items/{itemId})
	UpdateMenuItem(ctx context.Context, request UpdateMenuItemRequestObject) (UpdateMenuItemResponseObject, error)
	// ListPartnerOrders Poll for orders
	// (GET /orders)
	ListPartnerOrders(ctx context.Context, request ListPartnerOrdersRequestObject) (ListPartnerOrdersResponseObject, error)
	// AcceptOrder Accept an order and give an ETA
	// (POST /orders/{orderId}/accept)
	AcceptOrder(ctx context.Context, request AcceptOrderRequestObject) (AcceptOrderResponseObject, error)
	// RejectOrder Reject an order with a reason
	// (POST /orders/{orderId}/reject)
	RejectOrder(ctx context.Context, request RejectOrderRequestObject) (RejectOrderResponseObject, error)
	// AdvanceOrderStatus Move an order to the next status
	// (POST /orders/{orderId}/status)
	AdvanceOrderStatus(ctx context.Context, request AdvanceOrderStatusRequestObject) (AdvanceOrderStatusResponseObject, error)
	// ListPartnerRescueOffers Own rescue offers
	// (GET /rescue-offers)
	ListPartnerRescueOffers(ctx context.Context, request ListPartnerRescueOffersRequestObject) (ListPartnerRescueOffersResponseObject, error)
	// CreateRescueOffer Create a rescue offer for one menu item
	// (POST /rescue-offers)
	CreateRescueOffer(ctx context.Context, request CreateRescueOfferRequestObject) (CreateRescueOfferResponseObject, error)
	// CancelRescueOffer Cancel a rescue offer early
	// (DELETE /rescue-offers/{offerId})
	CancelRescueOffer(ctx context.Context, request CancelRescueOfferRequestObject) (CancelRescueOfferResponseObject, error)
	// GetPartnerVenue Own venue profile
	// (GET /venue)
	GetPartnerVenue(ctx context.Context, request GetPartnerVenueRequestObject) (GetPartnerVenueResponseObject, error)
	// UpdatePartnerVenue Update accepting_orders, minimum order amount, schedule, webhook URL
	// (PATCH /venue)
	UpdatePartnerVenue(ctx context.Context, request UpdatePartnerVenueRequestObject) (UpdatePartnerVenueResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

